// ============================================================
// RETRIEVAL: basic keyword/term-overlap search over a hardcoded
// FAQ knowledge base. No embeddings, no vector DB, no API cost.
//
// LIMITATION (read this before you ship it): this only matches
// on shared words. "when will my order get here" will NOT match
// "shipping time" unless you add synonyms. For paraphrase-heavy
// traffic, swap this node for n8n's Embeddings + In-Memory Vector
// Store nodes instead.
//
// Replace faqKB below with your real FAQ data, or load it from a
// Google Sheet / Postgres / JSON file node upstream of this one
// instead of hardcoding it here.
// ============================================================

const faqKB = [
  {
    id: "shipping_time",
    question: "How long does shipping take?",
    answer: "Standard shipping takes 3-5 business days within India. Express shipping (extra cost) takes 1-2 business days."
  },
  {
    id: "return_policy",
    question: "What is your return policy?",
    answer: "You can return any unused item within 7 days of delivery for a full refund. Items must be in original packaging."
  },
  {
    id: "payment_methods",
    question: "What payment methods do you accept?",
    answer: "We accept UPI, credit/debit cards, net banking, and cash on delivery for orders under Rs 5000."
  },
  {
    id: "order_tracking",
    question: "How do I track my order?",
    answer: "You'll receive a tracking link via SMS and email once your order ships. You can also check order status in the 'My Orders' section."
  },
  {
    id: "cancel_order",
    question: "Can I cancel my order?",
    answer: "Orders can be cancelled within 1 hour of placing them, before they're packed. After that, you'll need to use the return process instead."
  }
];

const userMessage =
  ($json.body && ($json.body.message || $json.body.text)) ||
  $json.message ||
  '';

function tokenize(str) {
  return (str || '')
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean);
}

const stopwords = new Set([
  'the','a','an','is','are','do','does','how','what','can',
  'i','my','your','you','to','for','of','in','on','it','this','that','will','get'
]);

function keywords(str) {
  return tokenize(str).filter(w => !stopwords.has(w));
}

const queryWords = keywords(userMessage);

function scoreEntry(entry) {
  const entryWords = keywords(`${entry.question} ${entry.answer}`);
  const entryWordSet = new Set(entryWords);
  let overlap = 0;
  for (const w of queryWords) {
    if (entryWordSet.has(w)) overlap += 1;
  }
  return queryWords.length ? overlap / queryWords.length : 0;
}

const scored = faqKB
  .map(entry => ({ ...entry, score: scoreEntry(entry) }))
  .sort((a, b) => b.score - a.score);

const topMatches = scored.filter(e => e.score > 0).slice(0, 3);

const contextText = topMatches.length
  ? topMatches.map(e => `Q: ${e.question}\nA: ${e.answer}`).join('\n\n')
  : 'NO_RELEVANT_CONTEXT_FOUND';

return [{
  json: {
    userMessage,
    topMatches,
    contextText,
    hasContext: topMatches.length > 0
  }
}];

// Parse the LLM's JSON response and defensively fall back if it
// returns malformed JSON (it will, occasionally -- plan for it).

const raw = $json.choices?.[0]?.message?.content || '';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    answer: "Sorry, I'm having trouble answering right now -- let me get a human to help you.",
    confidence: 0
  };
}

let confidence = Number(parsed.confidence);
if (isNaN(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(1, confidence));

return [{
  json: {
    answer: parsed.answer || "Let me get a human to help you with that.",
    confidence,
    message: $('Retrieve Context (Keyword Search)').item.json.userMessage
  }
}];

